#include "metalrobo/HeterogeneousWorld.hpp"
#include "metalrobo/MetalWorld.hpp"
#include <algorithm>
#include <cstring>
#include <iostream>
#include <vector>
#include <iomanip>
template<class T>bool slice(const std::vector<T>&a,const std::vector<T>&b,size_t offset,size_t count){return a.size()>=offset+count&&b.size()>=offset+count&&std::memcmp(a.data()+offset,b.data()+offset,count*sizeof(T))==0;}
template<class T>std::vector<T> twice(std::span<const T> s){std::vector<T>v(s.begin(),s.end());v.insert(v.end(),s.begin(),s.end());return v;}
int main(int argc,char**argv){if(argc!=4)return 2;
 auto m=metalrobo::makeFreeSphereEngineModel();m.world.gravityAndTimestep={0,0,0,.001f};m.defaultQ[1]=.0099f;m.defaultV[0]=1.f;m.defaultV[1]=-1.f;m.shapes[1].dimensions={.01f,0,0,0};m.shapes[1].contactRestAndBoundingRadius={.001f,0,.01f,0};for(auto&x:m.materials){x.friction={.5f,.5f,0,0};x.response={0,0,0,0};}
 MRBodyStateGPU ground{};ground.position.w=1;ground.orientation.w=1;ground.flagsAndIndices[0]=MR_MOTION_STATIC;ground.flagsAndIndices[1]=MR_INVALID_INDEX;std::vector<MRBodyStateGPU>scene{ground};
 metalrobo::DiscreteRodMaterial mat;mat.radius=.003;mat.density=1000;mat.youngModulus=1.e5;metalrobo::HeterogeneousRodProgram rod;rod.instanceId="mixed_test_rod";rod.model=metalrobo::makeStraightSutureRod(3,.04,mat);rod.defaultState=metalrobo::makeDiscreteElasticRodDefaultState(rod.model);for(auto&p:rod.defaultState.positions){p[0]-=.02;p[1]=.0228;}rod.collision.enableCCD=false;rod.collision.contactOffset=.001;rod.stepConfig.gravity={0,0,0};rod.stepConfig.timestep=.001;
 const std::vector<metalrobo::HeterogeneousWorldComponent>components{{&m,"body",scene}};const std::vector<metalrobo::HeterogeneousRodProgram> rods{rod};metalrobo::HeterogeneousWorld hw;metalrobo::EngineModelComposeConfig compose;compose.gravityAndTimestep={0,0,0,.001f};auto hd=metalrobo::composeHeterogeneousWorld(components,rods,hw,compose);if(!hd.succeeded())return 3;metalrobo::CompiledWorld world;if(!metalrobo::compileMetalWorld(hw,world).succeeded())return 4;
 auto q=twice<float>(hw.model.defaultQ);auto v=twice<float>(hw.model.defaultV);auto bodies=twice<MRBodyStateGPU>(hw.defaultSceneBodies);auto nodes=twice<MRRodNodeStateGPU>(world.defaultRodNodes());auto edges=twice<MRRodEdgeStateGPU>(world.defaultRodEdges());size_t nc=world.defaultRodNodes().size(),ec=world.defaultRodEdges().size();for(size_t i=nc;i<nodes.size();++i)nodes[i].position.y+=.5f;std::vector<float>effort(2*world.nv(),0);
 metalrobo::MetalWorldBatch batch{.environmentCount=2,.controlStepCount=1,.initialQ=q,.initialV=v,.efforts=effort,.initialSceneBodies=bodies,.initialRodNodes=nodes,.initialRodEdges=edges};metalrobo::MetalWorldStepConfig cfg;cfg.timestepSeconds=.001f;cfg.physicsSubsteps=1;cfg.velocityIterations=2;cfg.finalVelocityIterations=0;cfg.ccdMode=metalrobo::MetalWorldCCDMode::disabled;cfg.applyBodyDamping=false;cfg.captureContactEvidence=true;
 std::vector<metalrobo::MetalWorldResult> out(3),repeat(3);std::vector<metalrobo::MetalWorldDiagnostics> diag;for(int i=0;i<3;++i){metalrobo::MetalWorldConfig owner;owner.metallibPath=argv[i+1];metalrobo::MetalWorldContext ctx(owner);diag.push_back(ctx.run(world,batch,cfg,out[i]));ctx.run(world,batch,cfg,repeat[i]);}
 auto eqenv=[&](const auto&a,const auto&b,int env){return slice(a.finalQ,b.finalQ,env*world.nq(),world.nq())&&slice(a.finalV,b.finalV,env*world.nv(),world.nv())&&slice(a.finalSceneBodies,b.finalSceneBodies,env*hw.defaultSceneBodies.size(),hw.defaultSceneBodies.size())&&slice(a.finalRodNodes,b.finalRodNodes,env*nc,nc)&&slice(a.finalRodEdges,b.finalRodEdges,env*ec,ec);};
 std::cout<<std::setprecision(10)<<"{\"runs\":[";
 for(int i=0;i<3;i++){if(i)std::cout<<",";if(out[i].statuses.size()<2||out[i].contactStatuses.size()<2)return 5;std::cout<<"{\"succeeded\":"<<(diag[i].succeeded()?"true":"false")<<",\"successful_steps\":"<<diag[i].successfulStepCount<<",\"failed_steps\":"<<diag[i].failedStepCount<<",\"rigid_matches_baseline\":"<<(eqenv(out[0],out[i],1)?"true":"false")<<",\"repeated_env0\":"<<(eqenv(out[i],repeat[i],0)?"true":"false")<<",\"repeated_env1\":"<<(eqenv(out[i],repeat[i],1)?"true":"false")<<",\"env\":[";for(int e=0;e<2;e++){if(e)std::cout<<",";auto&s=out[i].statuses[e];auto&c=out[i].contactStatuses[e];bool restored=slice(out[i].finalQ,q,e*world.nq(),world.nq())&&slice(out[i].finalV,v,e*world.nv(),world.nv())&&slice(out[i].finalSceneBodies,bodies,e*hw.defaultSceneBodies.size(),hw.defaultSceneBodies.size())&&slice(out[i].finalRodNodes,nodes,e*nc,nc)&&slice(out[i].finalRodEdges,edges,e*ec,ec);std::cout<<"{\"status\":"<<s.code<<",\"contact_code\":"<<c.code<<",\"contacts\":"<<c.activeContacts<<",\"islands\":"<<c.islandCount<<",\"queue_flags\":"<<c.queueFlags<<",\"sweeps\":"<<c.solverIterations<<",\"normal_residual\":"<<c.residuals.y<<",\"restored\":"<<(restored?"true":"false")<<"}";}std::cout<<"]}";}std::cout<<"]}\n";
}
